import sys

input_lines = sys.stdin.readlines()


def solver(n, m):
    first = 0
    second = 0
    copy_n = n
    point = m if m % 2 == 0 else m + 1

    while copy_n != point // 2:
        if copy_n > point // 2:
            first += copy_n - point // 2
            copy_n = point // 2
        if copy_n < point // 2:
            copy_n *= 2
            first += 1

    first += 1 if m % 2 == 0 else 2

    copy_n = n
    while copy_n != m:
        if copy_n < m:
            copy_n *= 2
        else:
            second += copy_n - m
            break
        second += 1

    return min(first, second)


n, m = map(int, input_lines[0].split())

if n > m:
    print(n - m)
    sys.exit()

data = {n: n}
find = 0

while True:
    new_map = {}

    for i in data.keys():
        x = int(i)

        if x - 1 >= 1:
            new_map[x - 1] = x - 1
            if x - 1 == m:
                print(find + 1)
                sys.exit()

        if x * 2 <= m * 1.5:
            new_map[x * 2] = x * 2
            if x * 2 == m:
                print(find + 1)
                sys.exit()

    data = new_map
    find += 1

